interface SbShot { id:string;dur?:number;move?:string;camera_move?:string;prompt?:string;prompt_image?:string;prompt_video?:string;content?:string;action?:string;scene?:string;scene_name?:string;location?:string;shot_size?:string;angle?:string;lighting?:string;sound?:string;lens?:string;actor_refs?:string[];prop_refs?:string[];scene_ref?:string;style_refs?:string[];lines?:{speaker:string;line:string}[] }
const refTab=ref<'shots'|'frames'|'keyframes'|'lines'>('shots'),sbBoards=ref<string[]>([]),sbBoard=ref(''),sbShots=ref<SbShot[]>([]),assetRegistry=ref<AssetRegistryItem[]>([]),sbLoading=ref(false)
const coverage=ref<Record<string,'done'|'running'|'queued'|'generating'|'awaiting_import'|'error'|'pending'>>({}),coverageCounts=ref({total:0,done:0,running:0,error:0,pending:0,queued:0,generating:0,awaiting_import:0}),selectedShots=ref<Set<string>>(new Set()),selectedShotId=ref(''),regeneratingPrompt=ref('')
const ctype=ref<MediaType>('image'),prompt=ref(''),promptArea=ref<HTMLTextAreaElement|null>(null),refs=ref<RefItem[]>([]),refSeq=ref(1),vendorSel=ref(''),vendors=ref<Vendor[]>([]),note=ref(''),running=ref(false),items=ref<CreateItem[]>([]),galleryLoading=ref(false),galleryScope=ref<'current'|'all'>('current')
const assembledPrompt=ref(''),assembledNegative=ref(''),assembledAssetRefs=ref<string[]>([]),assembledAssetContext=ref<CreateItem['asset_context']|null>(null),assembledPromptJson=ref<Record<string,unknown>|null>(null),assembledSourceHash=ref(''),mentionOpen=ref(false),mentionQuery=ref('')
const lightboxImages=ref<string[]>([]),lightboxIndex=ref(0),lightboxVisible=ref(false),framesInfo=ref<FramesInfo|null>(null),framesLoading=ref(false),versions=ref<AnalysisMeta[]>([]),kfVersion=ref(''),analysis=ref<Analysis|null>(null),kfLoading=ref(false),script=ref<ScriptData|null>(null),pollTimer=ref<number|undefined>(),actorMode=ref<'baseline'|'stateful'>('stateful'),actorPerformanceUsed=ref(false),actorWarnings=ref<string[]>([])
const chatgptRunPanel=ref<InstanceType<typeof ChatGPTRunPanel>|null>(null),pendingChatGPTJobIds=ref<string[]>([])
let seq=0
const allShotsSelected=computed(()=>sbShots.value.length>0&&selectedShots.value.size===sbShots.value.length),someShotsSelected=computed(()=>selectedShots.value.size>0&&!allShotsSelected.value)
const isVisual=computed(()=>ctype.value==='image'||ctype.value==='video')
const mediaLabels:Record<MediaType,string>={image:'图片',video:'视频',music:'音乐',speech:'语音'}
const characterId=ref(''),voiceId=ref(''),characters=ref<{id:string;name?:string}[]>([])
const characterLabels=computed(()=>Object.fromEntries(characters.value.map(c=>[c.id,c.name||c.id])))
const modelChoices=computed(()=>vendors.value.filter(v=>v.enabled && (isVisual.value||v.id==='minimax')).flatMap(v=>{
  const slots=ctype.value==='image'?['image','image_edit']:[ctype.value]
  return slots.filter(slot=>!!(v.models as any)?.[slot]).map(slot=>({vendor:v,slot,label:`${v.label||v.id} · ${(v.models as any)[slot]}${slot==='image_edit'?'（需参考图）':''}`}))
}))
const vendorOptions=computed(()=>modelChoices.value.map(x=>x.label))
const currentChoice=computed(()=>modelChoices.value.find(x=>x.label===vendorSel.value))
const currentVendor=computed(()=>currentChoice.value?.vendor)
const selectedModelSlot=computed(()=>currentChoice.value?.slot||ctype.value)
const imageMode=computed(()=>'image_edit'===selectedModelSlot.value?'edit' as const:'generate' as const)
const isChatGPTQueue=computed(()=>ctype.value==='image' && currentVendor.value?.id==='chatgpt-queue')
const referenceLimit=computed(()=>{if(ctype.value==='video' && currentVendor.value?.video_capabilities?.known)return currentVendor.value.video_capabilities.max_refs;if(isChatGPTQueue.value)return 10;const v=currentVendor.value,n=Number((v as any)?.reference_limit);if(Number.isFinite(n)&&n>0)return Math.floor(n);const id=String(v?.id||'').toLowerCase(),m=String((v?.models as any)?.[selectedModelSlot.value]||'').toLowerCase();return id.includes('comfyui')?3:(id==='gemini'||m.includes('seedream')||m.includes('seedance')||m.includes('gpt-image')?10:3)})
const assembledPromptJsonText=computed(()=>assembledPromptJson.value?JSON.stringify(assembledPromptJson.value,null,2):''),mentionCandidates=computed(()=>refs.value.filter(r=>!mentionQuery.value||`${r.label} ${r.path} ${r.token}`.toLowerCase().includes(mentionQuery.value.toLowerCase())))
const shotGroups=computed(()=>{const m=new Map<string,SbShot[]>();for(const s of sbShots.value){const k=String(s.scene_name||s.scene||s.location||'未分场景').trim()||'未分场景';if(!m.has(k))m.set(k,[]);m.get(k)!.push(s)}return [...m].map(([key,shots])=>({key,label:key==='room'?'室内场景':key==='field'?'室外场景':key,shots}))})
const hiddenEntries=ref<HiddenEntries>({}),galleryNow=ref(Date.now())
const displayedItems=computed(()=>visibleEntries(items.value,hiddenEntries.value))
const abnormalCount=computed(()=>displayedItems.value.filter(i=>isAbnormal(i,galleryNow.value)).length)
const hiddenCount=computed(()=>items.value.filter(it=>(it as any).gallery_hidden_status!==it.status).length-displayedItems.value.length)
const galleryGroups=computed(()=>groupGalleryEntries(displayedItems.value))
const hiddenKey=()=>`wb.${app.current}.gallery.hidden.v1`
function saveHidden(value:HiddenEntries){try{localStorage.setItem(hiddenKey(),JSON.stringify(value));hiddenEntries.value=value}catch{window.alert('浏览器未能保存清理结果，请检查本地存储空间。')}}
function cleanGallery(){saveHidden(hideAbnormal(items.value,hiddenEntries.value))}
function restoreGallery(){saveHidden({})}
watch(()=>app.current,()=>{items.value=[];try{hiddenEntries.value=readHidden(localStorage.getItem(hiddenKey()))}catch{hiddenEntries.value={}}},{immediate:true})
const visibleGalleryGroups=computed(()=>galleryScope.value==='current'&&selectedShotId.value?galleryGroups.value.filter(g=>g.entries.some(i=>i.shot_id===selectedShotId.value&&i.board===sbBoard.value)):galleryGroups.value)
function outputPath(item:CreateItem,o:string){const p=String(o||'').replace(/\\/g,'/');return p.startsWith('projects/')?p:p.startsWith('创作/')?`projects/${app.current}/${p}`:`projects/${app.current}/创作/${item.id}/${p}`}
function shotPrompt(s:SbShot){if(ctype.value==='music')return s.sound||'';if(ctype.value==='speech')return(s.lines||[]).map(l=>l.line).join('\n');return ctype.value==='video'?s.prompt_video||s.action||s.content||'':s.prompt_image||s.prompt||s.content||s.action||''}
function assetThumb(a:AssetRegistryItem){return a.path?mediaUrl(`projects/${app.current}/${a.path}`):''}
function shotAssetItems(s:SbShot){const values=[s.scene_ref,...(s.actor_refs||[]),...(s.prop_refs||[]),...(s.style_refs||[])].filter(Boolean) as string[],seen=new Set<string>();return values.map(ref=>assetRegistry.value.find(a=>a.ref===ref)).filter((a):a is AssetRegistryItem=>{if(!a||!a.path||seen.has(a.ref))return false;seen.add(a.ref);return true})}
function tagRefs(input:RefItem[]){return input.map(r=>({...r,token:r.token&&/^@ref\d+$/.test(r.token)?r.token:`@ref${refSeq.value++}`}))}
function insertRefIntoPrompt(item:RefItem){const token=item.token||tagRefs([item])[0].token!,el=promptArea.value,pos=el?.selectionStart??prompt.value.length,before=prompt.value.slice(0,pos),match=before.match(/@[\w.-]*$/);prompt.value=(match?before.slice(0,-match[0].length):before+(before&&!/\s$/.test(before)?' ':''))+token+' '+prompt.value.slice(pos);mentionOpen.value=false;requestAnimationFrame(()=>el?.focus())}
function addRef(item:RefItem){if(!isVisual.value)return;if(refs.value.some(r=>r.path===item.path)){insertRefIntoPrompt(item);return}if(refs.value.length>=referenceLimit.value){window.alert(`当前厂商最多接收 ${referenceLimit.value} 张参考图；资产仍会写入提示词，请先移除一张`);return}const r=tagRefs([item])[0];refs.value.push(r);insertRefIntoPrompt(r)}
function removeRef(path:string){const r=refs.value.find(x=>x.path===path);refs.value=refs.value.filter(x=>x.path!==path);if(r?.token){const re=new RegExp(r.token.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'(?!\\d)','g');prompt.value=prompt.value.replace(re,'')}}
function refInUse(path:string){return refs.value.some(r=>r.path===path)}
function onPromptInput(){const before=prompt.value.slice(0,promptArea.value?.selectionStart??prompt.value.length),m=before.match(/@([\w.-]*)$/);mentionOpen.value=!!m&&refs.value.length>0;mentionQuery.value=m?.[1]||''}
function withRefMentions(text:string){const ts=refs.value.map(r=>r.token).filter(Boolean);return ts.length?`${text}\n参考图引用：${ts.join('、')}`:text}
function openGalleryImage(item:CreateItem,i:number){lightboxImages.value=(item.outputs||[]).map(o=>mediaUrl(outputPath(item,o)));lightboxIndex.value=i;lightboxVisible.value=true}
async function loadBoards(){sbBoards.value=(projectFiles('分镜')||[]).filter(f=>f.endsWith('.json')&&f.startsWith('剧本_'));if(!sbBoards.value.length){sbBoard.value='';return}if(sbBoard.value)await loadShots()}
// 首次进入某板默认全选；同一板的重刷（批量任务完成回调等）保留用户手选，
// 否则用户挑好的子集会被后台完成事件静默重置为全选，再点批量即全镜付费生成。
let autoSelKey=''
async function loadShots(){const id=++seq,project=app.current,board=sbBoard.value;sbShots.value=[];assetRegistry.value=[];coverage.value={};if(!project||!board)return;sbLoading.value=true;try{const b:any=await fetchWhiteBoard(project,board);if(id!==seq)return;sbShots.value=(b.shots||[]) as SbShot[];try{assetRegistry.value=(await fetchAssets(project)).assets||[]}catch{assetRegistry.value=[]}try{const c=await fetchCreateCoverage(project,board,ctype.value==='video'?'video':'image');if(id!==seq)return;coverage.value=Object.fromEntries((c.shots||[]).map(x=>[x.shot_id,x.status]));coverageCounts.value=(c.counts||{}) as typeof coverageCounts.value}catch{coverage.value={}};if(autoSelKey!==`${app.current}|${sbBoard.value}`){selectedShots.value=new Set(sbShots.value.map(s=>s.id));autoSelKey=`${app.current}|${sbBoard.value}`}else{const ids=new Set(sbShots.value.map(s=>s.id));selectedShots.value=new Set([...selectedShots.value].filter(id=>ids.has(id)))}await refreshChatGPTRunJobs()}catch{if(id===seq)sbShots.value=[]}finally{if(id===seq)sbLoading.value=false}}
let fillSeq=0
async function fillFromShot(s:SbShot){if(!isVisual.value){selectedShotId.value=s.id;prompt.value=ctype.value==='music'?(s.sound||''):(s.lines||[]).filter(l=>l.speaker===characterId.value).map(l=>l.line).join('\n');return}if(!app.current||!sbBoard.value)return;const fid=++fillSeq;const project=app.current,boardName=sbBoard.value;selectedShotId.value=s.id;try{const b=await assembleCreateShot({project,board:boardName,shot_id:s.id,type:ctype.value as 'image'|'video',vendor_id:currentVendor.value?.id});if(fid!==fillSeq||project!==app.current||boardName!==sbBoard.value)return;assembledAssetContext.value=b.asset_context||null;assembledPromptJson.value=b.prompt_json||null;assembledAssetRefs.value=b.asset_refs||[];refs.value=tagRefs((b.refs||[]).map(r=>({path:r.path,purpose:r.purpose,reference_role:r.reference_role,target_time_seconds:r.target_time_seconds,usage:r.usage,label:`${s.id} ${r.purpose}${r.reference_role?` · ${r.reference_role}`:''}`,thumb:mediaUrl(`projects/${app.current}/${r.path}`)})));assembledNegative.value=b.negative||'';assembledSourceHash.value=b.source_hash||'';prompt.value=withRefMentions(b.prompt_assembled||shotPrompt(s));assembledPrompt.value=b.prompt_assembled||''}catch(e){if(fid!==fillSeq)return;toast(e instanceof Error?e.message:'镜头素材加载失败','err');assembledSourceHash.value='';refs.value=[];assembledAssetContext.value=null;assembledAssetRefs.value=[];assembledPromptJson.value=null;prompt.value=shotPrompt(s);assembledPrompt.value='';assembledNegative.value=''}}
async function regenerateShotPrompt(s:SbShot){if(!isVisual.value)return;if(!app.current||!sbBoard.value||regeneratingPrompt.value)return;regeneratingPrompt.value=s.id;try{const r=await regenerateCreateShotPrompt({project:app.current,board:sbBoard.value,shot_id:s.id,type:ctype.value as 'image'|'video'});const j=await trackJob(r.id,`${s.id} 重写提示词`);if(!j.success)throw new Error('提示词重写失败，请查看任务抽屉');await loadShots();const u=sbShots.value.find(x=>x.id===s.id);if(u)await fillFromShot(u)}catch(e){window.alert(e instanceof Error?e.message:'提示词重写失败')}finally{regeneratingPrompt.value=''}}
function toggleShot(id:string){const s=new Set(selectedShots.value);s.has(id)?s.delete(id):s.add(id);selectedShots.value=s}
function selectAllShots(){selectedShots.value=allShotsSelected.value?new Set():new Set(sbShots.value.map(s=>s.id))}
async function refreshChatGPTRunJobs(){if(!app.current||!sbBoard.value){pendingChatGPTJobIds.value=[];return}try{const jobs=(await fetchChatGPTJobs(app.current,{board:sbBoard.value,status:'queued',limit:200})).jobs;const selected=selectedShots.value;pendingChatGPTJobIds.value=jobs.filter(job=>!selected.size||selected.has(job.shot_id)).map(job=>job.id)}catch{pendingChatGPTJobIds.value=[]}}
async function queueChatGPT(shotIds:string[]){if(!app.current||!sbBoard.value||!shotIds.length)return;running.value=true;try{const queued=await queueChatGPTShots({project:app.current,board:sbBoard.value,shot_ids:shotIds,type:'image'});const ids=(queued.jobs||[]).map(job=>job.id).slice(0,20);pendingChatGPTJobIds.value=ids;await chatgptRunPanel.value?.start(ids);await refreshGallery();await loadShots()}catch(e){window.alert(e instanceof Error?e.message:'加入并执行 ChatGPT 队列失败')}finally{running.value=false}}
async function generate(){if(isChatGPTQueue.value){if(selectedShotId.value)await queueChatGPT([selectedShotId.value]);return}if(!app.current||!prompt.value.trim()||!currentVendor.value||(ctype.value==='image'&&imageMode.value==='edit'&&!refs.value.length)||(ctype.value==='speech'&&(!characterId.value||!voiceId.value.trim())))return;running.value=true;try{const r=await runCreate({project:app.current,type:ctype.value,video_options:ctype.value==='video'?videoOptions.value:undefined,model_slot:ctype.value==='image'?selectedModelSlot.value:undefined,character_id:ctype.value==='speech'?characterId.value:undefined,voice_id:ctype.value==='speech'?voiceId.value:undefined,prompt:prompt.value.trim(),refs:refs.value.map(x=>({path:x.path,ref_token:x.token,purpose:x.purpose||'镜头关联素材',reference_role:ctype.value==='video' ? (x.path===firstRef.value && ['first_frame','first_last'].includes(videoOptions.value.mode||'') ? 'first_frame' : x.path===lastRef.value && ['last_frame','first_last'].includes(videoOptions.value.mode||'') ? 'last_frame' : 'reference_image') : x.reference_role,target_time_seconds:x.target_time_seconds,usage:x.usage,source_item_id:x.source_item_id,panel_id:x.panel_id})),board:ctype.value==='music'?undefined:sbBoard.value||undefined,shot_id:ctype.value==='music'?undefined:selectedShotId.value||undefined,prompt_user:prompt.value.trim(),prompt_assembled:assembledPrompt.value||undefined,prompt_json:assembledPromptJson.value,asset_refs:assembledAssetRefs.value,negative:assembledNegative.value||undefined,vendor_id:currentVendor.value.id,note:note.value.trim()||undefined,source_hash:assembledSourceHash.value||undefined,acting_mode:actorMode.value,actor_performance_used:actorPerformanceUsed.value,actor_warnings:actorWarnings.value});trackCreationJob(r.id,`创作 ${mediaLabels[ctype.value]}`,app.current);await refreshGallery();await loadShots()}catch(e){window.alert(e instanceof Error?e.message:'启动失败')}finally{running.value=false}}
async function generateBatch(){if(!isVisual.value)return;if(isChatGPTQueue.value){await queueChatGPT([...selectedShots.value]);return}if(!app.current||!sbBoard.value||!currentVendor.value||!selectedShots.value.size)return;running.value=true;try{const r=await runCreateBatch({project:app.current,board:sbBoard.value,type:ctype.value as 'image'|'video',mode:ctype.value==='image'?imageMode.value:undefined,vendor_id:currentVendor.value.id,shot_ids:[...selectedShots.value]});trackCreationJob(r.id,`批量创作 ${ctype.value==='image'?'分镜图':'视频'}`,app.current);await refreshGallery();await loadShots()}catch(e){window.alert(e instanceof Error?e.message:'批量启动失败')}finally{running.value=false}}
const importInput=ref<HTMLInputElement|null>(null)
async function onChatGPTImport(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file||!app.current)return;try{const result=await importChatGPTPackage(app.current,file);window.alert(`已导入 ${result.imported} 镜`);await refreshGallery();await loadShots()}catch(e){window.alert(e instanceof Error?e.message:'导入失败')}finally{(event.target as HTMLInputElement).value=''}}
let gallerySeq=0
async function refreshGallery(){if(!app.current)return;const request=++gallerySeq,project=app.current;galleryLoading.value=true;try{const result=await fetchCreate(project);if(request===gallerySeq&&project===app.current){items.value=result.items||[];galleryNow.value=Date.now()}}catch{if(request===gallerySeq&&project===app.current)items.value=[]}finally{if(request===gallerySeq)galleryLoading.value=false}}
function trackCreationJob(id:number,label:string,project:string){void trackJob(id,label).then(()=>{if(app.current===project){void loadBasics();void refreshGallery();void loadShots();void loadFrames();void loadKeyframeVersions()}})}
async function onChatGPTRunCompleted(){await refreshGallery();await loadShots()}
async function removeItem(id:string){if(!app.current||!window.confirm('确定删除该创作记录及其产出？'))return;try{await deleteCreateItem(app.current,id);await refreshGallery()}catch{window.alert('删除失败')}}
async function rerunItem(i:CreateItem){
  if(i.type==='speech'){window.location.assign('/studio/asset/voices');return}
  ctype.value=i.type
  if(i.board&&sbBoards.value.includes(i.board))sbBoard.value=i.board
  await nextTick()
  const choice=modelChoices.value.find(c=>c.vendor.id===i.vendor_id&&c.slot===(i.model_slot||(i.image_mode==='edit'?'image_edit':i.type)))
  if(choice)vendorSel.value=choice.label
  characterId.value=i.character_id||''
  await nextTick()
  voiceId.value=i.voice_id||''
  selectedShotId.value=i.shot_id||''
  prompt.value=i.prompt_user||i.prompt||''
  refs.value=isVisual.value?tagRefs((i.refs||[]).map(r=>typeof r==='string'?{path:r,label:'历史引用',thumb:mediaUrl(r)}:{path:r.path,label:'历史引用',token:r.ref_token,purpose:r.purpose,reference_role:r.reference_role,thumb:mediaUrl(`projects/${app.current}/${r.path}`)})):[]
}
async function loadFrames(){if(!app.current)return;framesLoading.value=true;try{framesInfo.value=await fetchFrames(app.current)}catch{framesInfo.value=null}finally{framesLoading.value=false}}
async function loadKeyframeVersions(){if(!app.current)return;try{versions.value=await fetchAnalysisList(app.current);if(!versions.value.some(v=>v.name===kfVersion.value)){let saved='';try{saved=localStorage.getItem(`wb.${app.current}.create.keyframes`)||''}catch{};kfVersion.value=versions.value.find(v=>v.name===saved)?.name||versions.value[0]?.name||''}}catch{versions.value=[]}}
async function loadKeyframes(){if(!app.current||!kfVersion.value)return;kfLoading.value=true;try{analysis.value=await fetchAnalysis(app.current,kfVersion.value)}catch{analysis.value=null}finally{kfLoading.value=false}}
async function loadCharacters(){const project=app.current;try{const data=await fetchScriptData(project);if(project===app.current)characters.value=data.characters?.characters||[]}catch{characters.value=[]}}
async function loadLines(){if(!app.current)return;try{script.value=await fetchLines(app.current)}catch{script.value=null}}
function defaultVendorOption(){return vendorOptions.value[0]||''}
async function loadVendors(){try{vendors.value=(await fetchEnvConfig()).vendors||[];if(!vendorOptions.value.includes(vendorSel.value)||vendorSel.value==='ChatGPT 原生生图 · 队列')vendorSel.value=defaultVendorOption()||(ctype.value==='image'?'ChatGPT 原生生图 · 队列':'')}catch{vendors.value=[];vendorSel.value=''}}
// 项目/分镜切换：全量重拉。ctype/imageMode 不在此列（由下方专用 watch 处理，避免一切换类型就双发 loadShots）。
watch(()=>[app.current,sbBoard.value,app.projects.length],()=>{if(app.current){void loadBoards();void loadFrames();void loadKeyframeVersions();void loadLines();void loadCharacters();void loadVendors();void refreshGallery()}},{immediate:true})
watch(()=>[app.current,sbBoard.value],()=>{fillSeq++;selectedShotId.value='';prompt.value='';refs.value=[];assembledPrompt.value='';assembledPromptJson.value=null;assembledAssetRefs.value=[];assembledNegative.value='';characterId.value='';voiceId.value=''})
// ComfyUI 内置的两套工作流按是否有参考图自动切换；云端通用模型保持所选模型。
watch(()=>refs.value.length,count=>{
  if(ctype.value!=='image'||currentVendor.value?.id!=='local-comfyui')return
  const slot=count?'image_edit':'image'
  const choice=modelChoices.value.find(c=>c.vendor.id==='local-comfyui'&&c.slot===slot)
  if(choice)vendorSel.value=choice.label
})
watch(kfVersion,loadKeyframes)
watch(refTab,tab=>{if(tab==='frames')void loadFrames();if(tab==='keyframes')void loadKeyframeVersions()})
watch([characterId,()=>currentVendor.value?.id],()=>{const saved=items.value.slice().reverse().find(i=>i.type==='speech'&&i.character_id===characterId.value&&i.vendor_id===currentVendor.value?.id);voiceId.value=saved?.voice_id||''})
// 媒体类型/生图模式切换：重置厂商、重装配当前镜、刷新覆盖度（loadShots 内 seq 防护竞态）。
watch(ctype,()=>{refs.value=[];prompt.value='';assembledPrompt.value='';assembledPromptJson.value=null;assembledNegative.value='';assembledAssetRefs.value=[];assembledAssetContext.value=null;selectedShotId.value='';vendorSel.value=defaultVendorOption()||(ctype.value==='image'?'ChatGPT 原生生图 · 队列':'');const s=sbShots.value.find(x=>x.id===selectedShotId.value);if(s)void fillFromShot(s);if(app.current&&sbBoard.value)void loadShots()})
watch([items,displayedItems],()=>{if(pollTimer.value)window.clearInterval(pollTimer.value);pollTimer.value=undefined;const active=items.value.some(i=>['running','generating'].includes(i.status));if(active){const visibleActive=displayedItems.value.some(i=>['running','generating'].includes(i.status));pollTimer.value=window.setInterval(refreshGallery,visibleActive?2500:30000)}},{deep:true})
onBeforeUnmount(()=>{if(pollTimer.value)window.clearInterval(pollTimer.value)})
useBoardSelection(sbBoard, sbBoards, 'free')
</script>
<template>
  <div class="page-wide">
    <header class="mb-6"><h1 class="grad-text text-2xl font-black">⑧ 自由创作</h1><RouterLink to="/create" class="text-sm text-sky-300">返回三层创作台</RouterLink><p class="mt-1 text-xs text-slate-500">自由引用素材生成图片、视频或音乐；角色配音请前往素材生成的音色绑定。</p></header>
    <EmptyState v-if="!app.current" title="请先在左侧选择项目" />
    <div v-else class="grid grid-cols-1 items-start gap-5 xl:grid-cols-[minmax(0,1.7fr)_minmax(360px,0.9fr)]">
      <aside class="min-w-0 glass p-4" :style="{ '--glow': GLOW }">
        <div class="mb-3 flex items-center gap-2"><h3 class="text-xs font-bold text-slate-500">镜头与关联素材</h3><span class="flex-1"></span><StyledSelect v-model="sbBoard" class="w-56" :options="sbBoards" :storage-key="`wb.${app.current}.free.board`" placeholder="— 选择分镜 —" /></div>
        <div class="mb-3 grid grid-cols-4 gap-1 rounded-lg bg-black/30 p-1"><button v-for="t in [{k:'shots',label:'分镜'},{k:'frames',label:'逐帧'},{k:'keyframes',label:'关键帧'},{k:'lines',label:'台词'}]" :key="t.k" class="rounded-md px-1.5 py-1 text-2xs font-semibold" :class="refTab===t.k?'chip-active':'chip'" @click="refTab=t.k as typeof refTab">{{ t.label }}</button></div>
        <template v-if="refTab==='shots'">
          <div class="mb-3 flex flex-wrap items-center gap-2"><span class="text-xs-plus text-slate-500">点击镜头装配提示词，点击素材加入引用</span><span class="flex-1"></span><span class="rounded-full bg-white/5 px-2 py-1 text-2xs text-slate-400">覆盖 {{ coverageCounts.done }}/{{ coverageCounts.total }}</span><label class="flex cursor-pointer items-center gap-1.5 rounded-md border border-line px-2 py-1 text-2xs text-slate-300"><input type="checkbox" :checked="allShotsSelected" :indeterminate="someShotsSelected" :disabled="!sbShots.length" @change="selectAllShots" />{{ allShotsSelected?'全不选':'全选' }}</label><button v-if="isVisual" class="btn btn-sm" :disabled="running||!sbBoard||(!isChatGPTQueue&&!currentVendor)||!selectedShots.size" @click="generateBatch">{{ running?(isChatGPTQueue?'启动执行中…':'批量执行中…'):(isChatGPTQueue?`加入并执行（${Math.min(selectedShots.size,20)} 镜）`:`批量生成（${selectedShots.size} 镜）`) }}</button></div>
          <div v-if="sbLoading" class="py-10 text-center text-sm text-slate-500">加载分镜…</div><div v-else-if="!sbShots.length" class="py-10 text-center text-sm text-slate-500">没有剧本分镜</div>
          <div v-else class="max-h-[calc(100vh-15rem)] space-y-5 overflow-y-auto pr-2"><section v-for="group in shotGroups" :key="group.key" class="space-y-2"><div class="flex items-center gap-2 border-b border-line pb-1.5"><h4 class="text-xs font-bold text-slate-200">{{ group.label }}</h4><span class="rounded-full bg-white/5 px-1.5 py-0.5 text-2xs text-slate-500">{{ group.shots.length }} 镜</span></div><div class="grid grid-cols-1 gap-3 2xl:grid-cols-2">
            <article v-for="s in group.shots" :key="s.id" class="group relative overflow-hidden rounded-xl border bg-black/20 transition" :class="selectedShotId===s.id?'border-pink-400/70 ring-1 ring-pink-400/40':'border-line hover:border-pink-400/50'" @click="fillFromShot(s)">
              <div class="flex items-center gap-2 border-b border-line bg-black/25 px-2.5 py-2"><span class="rounded bg-sky-400/15 px-1.5 py-0.5 text-xs-plus font-black text-sky-300">{{ s.id }}</span><span class="truncate text-2xs text-slate-400">{{ s.move||s.shot_size }}</span><span class="ml-auto rounded px-1.5 py-0.5 text-2xs font-bold" :class="coverage[s.id]==='done'?'bg-emerald-500/20 text-emerald-300':coverage[s.id]==='error'?'bg-rose-500/20 text-rose-300':(['running','queued','generating','awaiting_import'] as string[]).includes(coverage[s.id])?'bg-sky-500/20 text-sky-300':'bg-white/5 text-slate-500'">{{ coverage[s.id]==='done'?'已导入':coverage[s.id]==='error'?'失败':coverage[s.id]==='queued'?'待 ChatGPT':coverage[s.id]==='awaiting_import'?'待导入':(['running','generating'] as string[]).includes(coverage[s.id])?'生成中':'未生成' }}</span></div>
              <div class="min-h-[154px] bg-slate-950/90 p-2.5"><div v-if="shotAssetItems(s).length" class="grid grid-cols-3 gap-2"><button v-for="asset in shotAssetItems(s)" :key="asset.ref" type="button" class="overflow-hidden rounded-md border border-line bg-black/30 text-left transition hover:border-cyan-300/70" :title="`引用 ${asset.ref}`" @click.stop="addRef({path:asset.path!,token:asset.ref,label:asset.name,thumb:assetThumb(asset),purpose:'镜头关联资产'})"><img :src="assetThumb(asset)" class="aspect-video w-full object-contain" loading="lazy" :alt="asset.name" /><span class="block truncate px-1 py-1 text-2xs text-cyan-200">{{ asset.name }}</span></button></div><div v-else class="flex min-h-[135px] items-center justify-center text-2xs text-slate-500">该镜头暂无关联素材</div></div>
              <div class="flex items-center gap-2 border-t border-line px-2.5 py-2"><label class="flex cursor-pointer items-center gap-1.5 text-2xs text-slate-400" @click.stop><input type="checkbox" :checked="selectedShots.has(s.id)" @change="toggleShot(s.id)" />执行</label><span class="line-clamp-1 flex-1 text-2xs text-slate-400" :title="shotPrompt(s)">{{ shotPrompt(s)||'未填写提示词' }}</span><button v-if="isVisual" class="btn btn-ghost btn-sm" :disabled="!!regeneratingPrompt" @click.stop="regenerateShotPrompt(s)">{{ regeneratingPrompt===s.id?'重写中…':'重写提示词' }}</button></div>
            </article>
          </div></section></div>
        </template>
        <template v-else-if="refTab==='frames'"><div v-if="framesLoading" class="py-10 text-center text-sm text-slate-500">加载逐帧…</div><div v-else-if="!framesInfo?.frames?.length" class="py-10 text-center text-sm text-slate-500">该项目还没有逐帧</div><div v-else class="modal-h-sm grid grid-cols-3 gap-1.5 overflow-y-auto pr-1"><button v-for="f in framesInfo.frames" :key="f.file" class="group relative overflow-hidden rounded-md border border-line" :class="{'border-pink-400/70 ring-1 ring-pink-400/50':refInUse(`projects/${app.current}/逐帧/每秒/${f.file}`)}" @click="addRef({path:`projects/${app.current}/逐帧/每秒/${f.file}`,label:fmtT(f.t),thumb:mediaUrl(`projects/${app.current}/逐帧/每秒/${f.file}`)})"><img :src="mediaUrl(`projects/${app.current}/逐帧/每秒/${f.file}`)" class="aspect-video w-full object-cover" loading="lazy" alt="逐帧" /><span class="absolute left-0.5 top-0.5 rounded bg-black/70 px-1 text-2xs text-emerald-300">{{ fmtT(f.t) }}</span></button></div></template>
        <template v-else-if="refTab==='keyframes'"><StyledSelect v-model="kfVersion" class="mb-2" :options="versions.map(v=>v.name)" :storage-key="`wb.${app.current}.create.keyframes`" placeholder="— 选择解构版本 —" /><div v-if="kfLoading" class="py-10 text-center text-sm text-slate-500">加载关键帧…</div><div v-else-if="!analysis?.shots?.length" class="py-10 text-center text-sm text-slate-500">该版本没有关键帧</div><div v-else class="modal-h-sm grid grid-cols-2 gap-1.5 overflow-y-auto pr-1"><template v-for="shot in (analysis as any).shots" :key="shot.id"><button v-for="kf in shot.keyframes||[]" :key="kf" class="group relative overflow-hidden rounded-md border border-line" @click="addRef({path:`projects/${app.current}/拉片/${kfVersion}/${kf}`,label:shot.id,thumb:mediaUrl(`projects/${app.current}/拉片/${kfVersion}/${kf}`)})"><img :src="mediaUrl(`projects/${app.current}/拉片/${kfVersion}/${kf}`)" class="aspect-video w-full object-cover" loading="lazy" alt="关键帧" /></button></template></div></template>
        <template v-else><div v-if="!script?.lines?.length" class="py-10 text-center text-sm text-slate-500">该项目还没有台词</div><div v-else class="modal-h-sm space-y-1.5 overflow-y-auto pr-1"><div v-for="(line,i) in script.lines" :key="i" class="rounded-lg border border-line-soft bg-black/25 p-2"><div class="mb-1 flex items-center gap-2 text-2xs text-slate-500"><span>{{ script.speakers[line.speaker]?.name||line.speaker }}</span><span>{{ fmtClock(line.t_in) }}–{{ fmtClock(line.t_out) }}</span><button class="ml-auto text-pink-300" @click="ctype==='speech'?(characterId=line.speaker,prompt=line.text):(prompt += `\n台词：${line.text}`)">＋插入</button></div><p class="text-xs text-slate-300">{{ line.text }}</p></div></div></template>
        <div v-if="isVisual" class="mt-4 border-t border-line-soft pt-3"><div class="mb-1.5 text-2xs font-bold text-slate-500">已引用（{{ refs.length }}/{{ referenceLimit }}）</div><div v-if="assembledAssetContext" class="mb-2 rounded-md border border-cyan-400/20 bg-cyan-500/5 px-2 py-1 text-2xs text-cyan-200/80">资产提炼已注入：人物 {{ assembledAssetContext.characters?.length||0 }} · 场景 {{ assembledAssetContext.scene?1:0 }} · 道具 {{ assembledAssetContext.props?.length||0 }}</div><div v-if="!refs.length" class="py-2 text-center text-2xs text-slate-500">点击素材加入引用</div><div v-else class="flex flex-wrap gap-1.5"><span v-for="r in refs" :key="r.path" class="flex items-center gap-1.5 rounded-lg border border-pink-400/30 bg-pink-500/10 py-1 pl-1 pr-1.5"><img :src="r.thumb" class="h-6 w-10 rounded object-cover" alt="" /><button class="max-w-36 truncate text-2xs text-pink-200" @click="insertRefIntoPrompt(r)">{{ r.token }} · {{ r.label }}</button><button class="btn-danger rounded px-1 transition" title="移除" @click="removeRef(r.path)">×</button></span></div></div>
      </aside>
      <!-- 右栏：创作台 + 产出画廊 -->
      <div class="min-w-0 space-y-5 xl:sticky xl:top-5">
        <section class="min-w-0 glass p-5" :style="{'--glow':GLOW}"><h3 class="mb-3 text-xs font-bold text-slate-500">创作台</h3><div class="mb-3 grid grid-cols-2 gap-1.5"><button v-for="t in [{k:'image',label:'参考图',hint:'静态构图与最终姿态'},{k:'video',label:'视频',hint:'连续动作演绎'},{k:'music',label:'音乐',hint:'独立配乐素材'}]" :key="t.k" class="rounded-xl border p-3 text-left" :class="ctype===t.k?'border-pink-400/60 bg-pink-500/15':'border-line-soft bg-black/25'" @click="ctype=t.k as MediaType"><div class="text-sm font-bold" :class="ctype===t.k?'text-pink-200':'text-slate-300'">{{ t.label }}</div><div class="mt-0.5 text-2xs text-slate-500">{{ t.hint }}</div></button></div><p v-if="ctype==='image'" class="mb-2 text-2xs text-slate-400">按参考图和模型自动路由；ComfyUI 随参考图切换工作流，云端保持所选模型。</p><div v-if="ctype==='speech'" class="mb-3 grid grid-cols-2 gap-2"><label class="text-2xs text-slate-400">角色<StyledSelect v-model="characterId" :options="characters.map(c=>c.id)" :labels="characterLabels" placeholder="选择角色" /></label><label class="text-2xs text-slate-400">音色 ID<input v-model="voiceId" class="input" placeholder="厂商音色 ID" /></label></div><label class="mb-1 block text-2xs text-slate-500">{{ ctype==='speech'?'朗读文本（只填写需要说出的内容）':ctype==='music'?'音乐描述（风格、乐器、情绪）':ctype==='video'?'视频动作描述':'图片描述' }}</label><textarea ref="promptArea" v-model="prompt" @input="onPromptInput" @keydown.esc="mentionOpen=false" class="textarea min-h-52" placeholder="输入画面描述；输入 @ 选择已引用素材，引用会传入模型"></textarea><div v-if="mentionOpen" class="mt-1 max-h-40 overflow-y-auto rounded-lg border border-pink-400/30 bg-slate-900 p-1"><button v-for="r in mentionCandidates" :key="r.token" class="flex w-full items-center gap-2 rounded px-2 py-1 text-left text-xs hover:bg-pink-500/15" @click="insertRefIntoPrompt(r)"><img :src="r.thumb" class="h-8 w-12 rounded object-cover" alt="" /><span class="text-pink-200">{{ r.token }}</span><span class="truncate text-slate-400">{{ r.label }}</span></button></div><details v-if="assembledPromptJsonText" class="mt-3 rounded-lg border border-cyan-400/20 bg-cyan-500/5"><summary class="cursor-pointer px-3 py-2 text-2xs font-semibold text-cyan-200">结构化提示 JSON</summary><pre class="max-h-64 overflow-auto whitespace-pre-wrap px-3 pb-3 text-2xs text-slate-400">{{ assembledPromptJsonText }}</pre></details><div class="mt-3 grid grid-cols-1 gap-3 sm:grid-cols-2"><label class="text-2xs text-slate-500">厂商 / 模型<StyledSelect v-model="vendorSel" class="mt-0.5" :options="vendorOptions" :storage-key="`wb.${app.current}.create.vendor.${ctype}`" placeholder="— 选择 —" /></label><label class="text-2xs text-slate-500">备注<input v-model="note" class="input mt-0.5" placeholder="可选" /></label></div><div v-if="ctype==='video'" class="space-y-3 mt-3"><VideoSettings v-model="videoOptions" :capability="currentVendor?.video_capabilities" />
<label class="block text-xs">时长（秒）<input v-model.number="videoOptions.duration" type="number" class="input" /></label>
<label v-if="['first_frame','first_last'].includes(videoOptions.mode||'')" class="block text-xs">首帧<select v-model="firstRef" class="input"><option value="">请选择引用素材</option><option v-for="r in refs" :key="r.path" :value="r.path">{{ r.label }}</option></select></label>
<label v-if="['last_frame','first_last'].includes(videoOptions.mode||'')" class="block text-xs">尾帧<select v-model="lastRef" class="input"><option value="">请选择引用素材</option><option v-for="r in refs" :key="r.path" :value="r.path">{{ r.label }}</option></select></label>
<p class="text-xs text-slate-400">首尾帧模式请仅保留指定帧；文生视频请移除引用素材。其余素材不会被静默丢弃。</p></div><button class="btn mt-4 w-full justify-center py-2.5 text-base" :disabled="running||!prompt.trim()||!vendorSel||(ctype==='image'&&imageMode==='edit'&&!refs.length)||(ctype==='speech'&&(!characterId||!voiceId.trim()))" @click="generate">{{ running?'提交中…':`生成${mediaLabels[ctype]}` }}</button><p v-if="isVisual" class="mt-2 text-center text-2xs text-slate-500">引用 {{ refs.length }}/{{ referenceLimit }} 个素材</p></section>
        <!-- 产出画廊 -->
        <div v-if="isChatGPTQueue" class="space-y-3">
          <ChatGPTRunPanel ref="chatgptRunPanel" :project="app.current" :job-ids="pendingChatGPTJobIds" :disabled="running" @completed="onChatGPTRunCompleted" />
          <div class="rounded-lg border border-violet-400/20 bg-violet-500/10 p-3 text-2xs text-violet-200"><div class="mb-2 font-semibold">手动恢复入口</div><p class="mb-2 text-violet-200/70">自动执行不可用时，仍可导入已有 ChatGPT 原图或生成包。</p><input ref="importInput" type="file" accept=".zip,.json,image/png,image/jpeg,image/webp" class="hidden" @change="onChatGPTImport" /><button class="btn btn-sm" @click="importInput?.click()">导入 ChatGPT 生成包</button></div>
        </div>
        <aside class="min-w-0 glass p-4" :style="{'--glow':GLOW}"><div class="mb-3 flex flex-wrap items-center gap-2"><h3 class="text-xs font-bold text-slate-500">产出画廊</h3><div class="flex-1"></div><button class="btn btn-ghost btn-sm" :disabled="!abnormalCount" title="隐藏当前项目失败、异常及生成超过24小时的记录；后端记录和文件保留" @click="cleanGallery">清理异常（{{ abnormalCount }}）</button><button v-if="hiddenCount" class="btn btn-ghost btn-sm" @click="restoreGallery">恢复显示（{{ hiddenCount }}）</button><button v-if="selectedShotId" class="btn btn-ghost btn-sm" @click="galleryScope=galleryScope==='current'?'all':'current'">{{ galleryScope==='current'?'查看全部':'只看当前镜' }}</button><button class="btn btn-ghost btn-sm" :disabled="galleryLoading" @click="refreshGallery">刷新</button></div><div v-if="galleryLoading&&!items.length" class="py-10 text-center text-sm text-slate-500">加载产出…</div><div v-else-if="!items.length" class="py-10 text-center text-sm text-slate-500">还没有创作产出</div><div v-else-if="!visibleGalleryGroups.length" class="py-10 text-center text-sm text-slate-500">当前范围没有可见产出（可切换全部或恢复显示）</div><div v-else class="modal-h space-y-4 overflow-y-auto pr-1"><section v-for="group in visibleGalleryGroups" :key="group.key" class="rounded-xl border border-line bg-black/10 p-2"><div class="mb-2 flex items-center justify-between px-1 text-xs-plus font-semibold text-cyan-200"><span>{{ group.label }}</span><span class="text-2xs text-slate-500">{{ group.entries.length }} 次产出</span></div><article v-for="it in group.entries" :key="it.id" class="glass glass-hover overflow-hidden p-3"><div class="mb-2 flex items-center gap-2"><span class="rounded-full px-2 py-0.5 text-2xs font-bold" :class="it.status==='done'?'bg-emerald-400/15 text-emerald-300':it.status==='error'?'bg-rose-400/15 text-rose-300':'bg-sky-400/15 text-sky-300'">{{ galleryStatus(it.status) }}</span><span class="rounded-full bg-white/5 px-2 py-0.5 text-2xs text-slate-400">{{ mediaLabels[it.type] }}{{ it.character_name?' · '+it.character_name:'' }}</span><span v-if="it.shot_id" class="rounded-full bg-cyan-400/10 px-2 py-0.5 text-2xs text-cyan-300">{{ it.shot_id }}</span><span class="flex-1 truncate text-2xs text-slate-500">{{ it.created_at||'' }}</span><button v-if="it.shot_id" class="btn btn-ghost btn-sm" :disabled="running" @click="rerunItem(it)">重新生成本镜</button><button class="btn-danger rounded px-1 transition" title="删除" @click="removeItem(it.id)">×</button></div><p class="mb-2 line-clamp-3 whitespace-pre-wrap text-xs-plus leading-relaxed text-slate-300" :title="it.prompt">{{ it.prompt }}</p><div v-if="it.outputs?.length" class="grid grid-cols-1 gap-2"><template v-for="(o,oi) in it.outputs" :key="oi"><button v-if="it.type==='image'" type="button" class="block w-full" :title="`放大查看 ${outputPath(it,o)}`" @click="openGalleryImage(it,oi)"><img :src="mediaUrl(outputPath(it,o))" class="aspect-video w-full rounded-md border border-line bg-black object-contain" loading="lazy" alt="点击放大产出" /></button><video v-else-if="it.type==='video'" :src="mediaUrl(outputPath(it,o))" controls class="aspect-video w-full rounded-md bg-black" preload="metadata"></video><audio v-else :src="mediaUrl(outputPath(it,o))" controls preload="metadata" class="w-full"></audio></template></div><p v-if="it.registration_error" class="text-amber-300 text-2xs">素材归档失败，原始产出已保留：{{ it.registration_error }}</p><p v-if="it.material_path" class="text-2xs text-slate-500">素材：{{ it.material_path }}</p><p v-if="it.status==='error'&&it.note" class="mt-2 rounded-md bg-rose-400/10 px-2 py-1 text-2xs text-rose-300">{{ it.note }}</p></article></section></div></aside>
      </div>
    </div>
  </div>
  <OverlayViewer :images="lightboxImages" :index="lightboxIndex" :visible="lightboxVisible" @close="lightboxVisible=false" @update-index="lightboxIndex=$event" />
</template>
